import json
import time

# ---- Cấu hình ----
BRANCH_KEYWORD = "Bà Triệu"   # chi nhánh như bản cũ: King Deli1 Bà Triệu (value 48)
TIMEOUT = 15.0
STEP = 0.2


def wait_until(predicate, what):
    """Vòng lặp ngắn: tối đa TIMEOUT giây, mỗi lần STEP giây."""
    deadline = time.time() + TIMEOUT
    while time.time() < deadline:
        try:
            if predicate():
                return True
        except Exception:
            pass
        time.sleep(STEP)
    raise RuntimeError(f"Timeout chờ: {what}")


def el_exists(sel):
    return bool(js(f"!!document.querySelector({json.dumps(sel)})"))


def fill_text(sel, text):
    """Click vào ô, chọn hết, gõ nội dung; nếu không khớp thì gán value + dispatch input/change."""
    wait_until(lambda: el_exists(sel), f"ô {sel}")
    box = js(f"""(()=>{{
        const e=document.querySelector({json.dumps(sel)});
        e.scrollIntoView({{block:'center'}});
        e.focus();
        const r=e.getBoundingClientRect();
        return [r.x+r.width/2, r.y+r.height/2];
    }})()""")
    click_at_xy(box[0], box[1])
    cdp('Input.dispatchKeyEvent', type='rawKeyDown', key='a', code='KeyA', commands=['selectAll'])
    cdp('Input.dispatchKeyEvent', type='keyUp', key='a', code='KeyA')
    type_text(text)
    press_key('Tab')
    time.sleep(0.2)

    got = js(f"document.querySelector({json.dumps(sel)}).value")
    if got != text:
        got = js("""(()=>{
            const e=document.querySelector(__SEL__);
            const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
            d.set.call(e, __VAL__);
            e.dispatchEvent(new Event('input',{bubbles:true}));
            e.dispatchEvent(new Event('change',{bubbles:true}));
            return e.value;
        })()""".replace("__SEL__", json.dumps(sel)).replace("__VAL__", json.dumps(text)))
    return got


JS_SELECT = """(()=>{
    const s=document.querySelector(__SEL__);
    if(!s) return {err:'no select'};
    const V=__VAL__, T=__TXT__;
    const idx=[...s.options].findIndex(o =>
        (V!==null && o.value===V) || (T!==null && o.text.includes(T)));
    if(idx<0) return {err:'no option', n:s.options.length};
    s.selectedIndex=idx;
    s.value=s.options[idx].value;
    s.dispatchEvent(new Event('input',{bubbles:true}));
    s.dispatchEvent(new Event('change',{bubbles:true}));
    return {value:s.value, text:s.options[idx].text};
})()"""


def select_by(sel, value=None, text_contains=None):
    code = (JS_SELECT.replace("__SEL__", json.dumps(sel))
                     .replace("__VAL__", json.dumps(value))
                     .replace("__TXT__", json.dumps(text_contains)))
    res = js(code)
    if not isinstance(res, dict) or "err" in res:
        raise RuntimeError(f"Không chọn được option cho {sel}: {res}")
    return res["value"]


def wait_option(sel, value):
    """Chờ danh sách option tải xong (có option với value cần chọn)."""
    check = f"""(()=>{{
        const s=document.querySelector({json.dumps(sel)});
        return !!s && [...s.options].some(o=>o.value==={json.dumps(value)} && !o.disabled);
    }})()"""
    wait_until(lambda: js(check), f"option {value} của {sel}")


# ---- Mở trang ----
new_tab("https://kingbbq.vn/dat-ban/")
wait_for_load()

wait_until(lambda: el_exists('#inputName') and el_exists('#inputDate')
           and el_exists('#inputHour') and el_exists('#inputRestaurant'),
           "form đặt bàn")

# ---- Điền họ tên, email (nếu có), SĐT, số người ----
fill_text('#inputName', NAME)
if el_exists('#inputEmail'):
    fill_text('#inputEmail', EMAIL)
fill_text('#inputPhone', PHONE)
fill_text('#inputNumber', str(PARTY))

# ---- Ngày ----
date_tag = js("document.getElementById('inputDate').tagName")
if date_tag == 'SELECT':
    # Ô ngày dạng select: thử theo dd/mm/yyyy, nếu không có thì chọn "Ngày mai"
    try:
        select_by('#inputDate', value=DATE_ISO, text_contains=DATE_DMY)
    except RuntimeError:
        select_by('#inputDate', text_contains='Ngày mai')
else:
    fill_text('#inputDate', DATE_DMY)

# ---- Chi nhánh (select): tìm theo nội dung, gán value, dispatch input + change ----
select_by('#inputRestaurant', text_contains=BRANCH_KEYWORD)

# ---- Giờ: chờ danh sách giờ tải xong rồi mới chọn ----
HOUR_VALUE = str(int(HHMM[:2]))     # "19"
MINUTE_VALUE = HHMM[3:5]            # "00"
wait_option('#inputHour', HOUR_VALUE)
select_by('#inputHour', value=HOUR_VALUE)

# ---- Phút ----
wait_option('#inputMinute', MINUTE_VALUE)
select_by('#inputMinute', value=MINUTE_VALUE)

# ---- Kiểm tra giá trị các ô, raise nếu sai ----
expected = {
    '#inputName': NAME,
    '#inputPhone': PHONE,
    '#inputNumber': str(PARTY),
    '#inputHour': HOUR_VALUE,
    '#inputMinute': MINUTE_VALUE,
}
if el_exists('#inputEmail'):
    expected['#inputEmail'] = EMAIL
if date_tag != 'SELECT':
    expected['#inputDate'] = DATE_DMY

actual = {}
for sel in expected:
    actual[sel] = js(f"document.querySelector({json.dumps(sel)}).value")

restaurant_text = js("""(()=>{const s=document.getElementById('inputRestaurant');
    return s.options[s.selectedIndex] ? s.options[s.selectedIndex].text : '';})()""")
if BRANCH_KEYWORD not in restaurant_text:
    raise RuntimeError(f"Chi nhánh sai: {restaurant_text!r}")

mismatch = {k: (expected[k], actual[k]) for k in expected if actual[k] != expected[k]}
if mismatch:
    raise RuntimeError(f"Giá trị các ô không đúng (mong đợi, thực tế): {mismatch}")

print("OK - đã điền form (chưa gửi):", actual, "| chi nhánh:", restaurant_text)
